    표8_상담적용: [
        {"상황":"하나님을 알지만 예배와 삶이 분리된 성도", "성경원리":"알되 영화롭게 하지 않는 것이 죄이다. 신앙은 지식에서 예배로, 예배에서 삶으로 이어져야 한다", "실제적용":"야고보서 2:17 행함이 없는 믿음은 그 자체가 죽은 것이라를 함께 읽으며 신앙 지식과 삶의 통합을 위한 구체적 실천을 계획한다"},
        {"상황":"감사보다 불평이 많은 성도", "성경원리":"감사하지 않는 것이 마음을 허망하게 하고 어둡게 한다. 감사가 영적 건강의 기준이다", "실제적용":"매일 하나님께 감사할 세 가지를 기록하는 감사 일기를 시작하게 하고 4주 후의 변화를 함께 점검한다"},
        {"상황":"삶의 의미와 목적을 찾지 못하는 성도", "성경원리":"생각이 허망해지는 것은 하나님을 영화롭게 하지 않는 것의 결과이다. 삶의 의미는 하나님을 영화롭게 하는 것에서 발견된다", "실제적용":"소교리문답 1문 인간의 제일 되는 목적은 하나님을 영화롭게 하고 영원히 그를 즐거워하는 것이라를 함께 묵상하며 삶의 목적을 재발견하게 한다"}
    ],
