        {"상황":"부모와의 관계가 깨진 자녀", "성경원리":"부모 공경은 첫 번째 약속 있는 계명이며(엡 6:2-3), 부모와의 화해는 하나님 앞에 올바른 자세이다", "실제적용":"부모와의 화해를 위한 구체적 단계(사과, 이해, 용서 구하기)와 경계 설정을 함께 안내"},
        {"상황":"언어폭력(비방, 험담)으로 공동체가 분열된 상황", "성경원리":"무익한 말을 하지 말고 덕을 세우는 선한 말을 하라(엡 4:29), 비방하는 자는 심판받는다(약 4:11)", "실제적용":"언어 정화를 위한 실천 방법(말 전에 생각하기, 긍정적 말하기 연습)과 공동체 화해 과정 안내"}
