        {"새찬송가":"491", "통일찬송가":"558", "제목":"사랑하는 주님 앞에", "선정이유":"하나님의 공정한 보응을 생각하며 선한 삶을 다짐하는 찬송"},
        {"새찬송가":"338", "통일찬송가":"396", "제목":"내 주의 지신 십자가", "선정이유":"우리의 행위에 대한 형벌을 대신 받으신 그리스도를 묵상하는 찬송"},
        {"새찬송가":"480", "통일찬송가":"551", "제목":"달고 오묘한 그 말씀", "선정이유":"하나님의 말씀대로 살려는 결단을 담은 찬송"}
