        {"새찬송가":"286", "통일찬송가":"343", "제목":"예수님이 말씀하시기를", "선정이유":"말씀대로 살 때 심판에 대비할 수 있음을 가르치는 찬송"},
        {"새찬송가":"457", "통일찬송가":"526", "제목":"주 예수 대문 밖에 서서", "선정이유":"받은 빛에 응답하도록 초청하는 찬송"}
