        {"대지":"2대지: 의로운 심판자는 불의할 수 없다", "내용":"심판자가 불의하다면 심판 자체가 무의미하다. 하나님의 심판이 의미있으려면 하나님이 의로우셔야 함", "예화_적용":"공정한 법정 시스템의 필요성을 통해 의로운 심판자의 필요성 설명"},
        {"대지":"결론", "내용":"하나님의 심판은 두려움이 아니라 소망이다. 세상의 불의가 반드시 바로잡힐 것이다. 그러나 그 전에 나 자신이 그 심판 앞에 서야 함을 잊지 말라", "예화_적용":"행 17:31 '정한 사람으로 세상을 공의로 심판하실 날을 작정하셨다'를 결론으로"}
