        {"대지":"서론", "내용":"인간은 왜 방향을 잃는가? GPS가 없으면 사람은 직선이 아닌 원을 그리며 걷는다고 한다. 하나님 없는 인간도 마찬가지다. '다 치우쳐' - 모든 사람이 하나님의 길에서 벗어났다", "예화_적용":"방향을 잃은 인간의 방황을 실제 심리·사회 현상과 연결"},
        {"대지":"1대지: 모두가 예외 없이 치우쳤다", "내용":"종교인, 철학자, 선한 사람도 하나님의 완전한 기준에서 벗어났다. '다'와 '하나도 없도다'는 예외를 허용하지 않음", "예화_적용":"사 64:6 '우리의 의는 다 더러운 옷 같으니라'를 인용"},
        {"대지":"2대지: 스스로 돌아올 수 없다", "내용":"무익하게 된 자는 스스로 회복할 수 없다. 외부에서 능력이 와야 한다. 복음이 바로 그 능력이다", "예화_적용":"죽은 자는 스스로 살아날 수 없듯 영적으로 죽은 인간은 하나님의 생명이 필요함"},
        {"대지":"결론", "내용":"내가 치우쳐 있음을 인정하는 것이 회복의 시작이다. 나를 회복하실 수 있는 분은 오직 하나님뿐이시다. 그분께 돌아오라", "예화_적용":"탕자가 '스스로 돌이켜'(눅 15:17) 아버지께 돌아온 이야기를 결론으로"}
