        {"새찬송가":"75", "통일찬송가":"68", "제목":"거룩하신 하나님", "선정이유":"한 분 하나님 앞에 함께 서는 경배"},
        {"새찬송가":"267", "통일찬송가":"196", "제목":"다 함께 일어나", "선정이유":"모든 민족이 한 하나님 앞에 함께 모임"}
