        {"상황":"열심히 신앙생활 하면 하나님이 복을 주실 것이라 생각하는 성도 (거래식 신앙)", "성경원리":"구원은 은혜의 원리 - 빚이 아닌 선물 (롬 4:4). 하나님과의 관계는 채무-채권 관계가 아님", "실제적용":"하나님과의 관계를 은혜와 사랑의 관계로 재정립하고 감사와 기쁨으로 신앙생활하도록 안내"}
