        {"교리":"행위 없는 칭의의 보편성", "설명":"아브라함(이방인의 조상이 되기 전)과 다윗(죄인)이 모두 행위 없이 의롭다 하심을 받음. 이신칭의는 특수 사례가 아닌 보편 원리", "관련구절":"롬 4:3,6; 갈 2:16"}
