        {"교리":"칭의의 시간적 우선성", "설명":"믿음으로 인한 칭의가 외적 의식보다 먼저임. 내적 믿음의 실재가 외적 표시보다 중요하며 선행함", "관련구절":"롬 10:9-10; 행 10:44-48"}
