        {"새찬송가":"279", "통일찬송가":"404", "제목":"믿음으로 가리라", "선정이유":"아브라함처럼 믿음의 발자국을 따라 걷는 삶"},
        {"새찬송가":"384", "통일찬송가":"523", "제목":"나 주의 도움 받고자", "선정이유":"믿음의 조상들을 따라 주의 도움으로 살아가는 삶"}
