        {"상황":"교회 내 다른 배경(교단, 문화)을 가진 성도들 간의 갈등", "성경원리":"율법에 속한 자나 아브라함의 믿음에 속한 자나 모두 아브라함의 후손 - 아브라함은 우리 모두의 조상 (롬 4:16)", "실제적용":"믿음 안에서 모두가 아브라함의 한 가족임을 가르치고 다양성 속의 통일을 그리스도 안에서 찾도록 안내"}
