        {"상황":"예배가 형식적이고 감동이 없다고 느끼는 성도", "성경원리":"믿음이 견고해질 때 하나님께 영광을 돌리게 됨 (롬 4:20). 예배의 감동은 믿음에서 나옴", "실제적용":"예배의 감동을 먼저 추구하기보다 하나님의 약속에 대한 믿음을 먼저 견고히 하고 그 믿음에서 자연스럽게 영광이 흘러나오도록 안내"}
