        {"대지":"서론", "내용":"우리의 믿음이 얼마나 충만한가? 바울은 아브라함의 믿음을 πεπληροφορημένος - 완전히 채워진 확신이라고 묘사한다. 반쪽짜리 확신이 아닌 완전한 확신이다", "예화_적용":"가득 찬 항구와 반쯤 찬 항구의 차이"},
        {"대지":"1대지: 약속하신 것 - 신실하신 하나님", "내용":"하나님은 약속하셨다. 그 약속은 확실하다. 하나님의 신실성 - 거짓말하실 수 없으시고 (히 6:18) 후회하지 않으심 (민 23:19). 약속의 근거는 하나님의 성품", "예화_적용":"인품이 확실한 사람의 약속은 더 신뢰함"},
        {"대지":"2대지: 능히 이루실 수 있음 - 전능하신 하나님", "내용":"δυνατός - 능력 있으신, 전능하신. 약속을 지키고 싶어도 능력이 없으면 소용없음. 하나님은 신실하실 뿐 아니라 전능하심. 두 속성이 함께 믿음의 기초", "예화_적용":"의사가 진단을 정확히 하고 능력도 있어야 환자가 신뢰함"},
        {"대지":"결론", "내용":"아브라함은 약속하신 하나님의 신실성과 전능성을 충만히 확신했다. 우리도 그리스도 안에서 약속하신 하나님을 충만히 확신하자. 요동하지 않는 믿음이 우리의 소망이다", "예화_적용":"롬 8:38-39 어떤 것도 우리를 하나님의 사랑에서 끊을 수 없음"}
