        {"상황":"오랫동안 기도했지만 이루어지지 않아 하나님의 약속을 의심하는 성도", "성경원리":"약속하신 것을 능히 이루실 것에 대한 충만한 확신 (롬 4:21). 하나님의 때가 있음", "실제적용":"하나님의 능력과 신실성은 변함없지만 하나님의 때가 우리의 기대와 다를 수 있음을 설명하고 아브라함이 오랜 기다림 후에 이삭을 받은 것처럼 인내로 신뢰하도록 안내"}
