        {"원어":"διό (디오)", "의미_문법":"그러므로 - 논리적 결론을 이끄는 접속사. 19-21절의 아브라함의 믿음에 대한 결론", "설교포인트":"믿음의 결론 - 의로 여기심"},
        {"원어":"ἐλογίσθη αὐτῷ εἰς δικαιοσύνην (엘로기스데 아우토 에이스 디카이오쉬넨)", "의미_문법":"이것이 그에게 의로 여기셨다 - 3절과 동일한 표현의 반복으로 4장 전체의 핵심 진술을 확인", "설교포인트":"4장의 결론 - 이런 믿음이 의로 여기심을 받음"}
