        {"대지":"서론", "내용":"바울은 19-21절에서 아브라함의 믿음을 자세히 묘사했다. 그리고 22절에서 결론을 맺는다: 그러므로 이것이 의로 여기셨다. 어떤 믿음인가? 약해지지 않고, 의심치 않고, 확신으로 가득 찬 믿음", "예화_적용":"논문의 결론 - 앞의 논증에서 도출되는 명확한 결론"},
        {"대지":"1대지: 이것이 의로 여기심을 받음", "내용":"이것(τοῦτο) - 19-21절의 믿음의 특성 전체. 현실을 알면서도 약해지지 않고, 의심치 않고, 견고해지고, 영광을 돌리는 믿음. 이것이 의로 여기심을 받는 믿음", "예화_적용":"품질 인증 - 특정 기준을 만족하는 믿음"},
        {"대지":"2대지: 4장의 핵심 진술 재확인", "내용":"3절에서 시작된 창 15:6의 인용이 22절에서 다시 확인됨. 4장 전체의 논증이 이 한 진술로 귀결: 믿음이 의로 여기심을 받음. 아브라함의 이야기 전체가 이 한 진리를 증언", "예화_적용":"4장을 마무리하는 핵심 선언"},
        {"대지":"결론", "내용":"그러므로 이것이 의로 여기셨다. 아브라함의 믿음이 그러했다. 우리도 이런 믿음으로 하나님 앞에 설 수 있다. 의로 여기심은 하나님의 선물이요 믿음은 그것을 받는 손이다", "예화_적용":"선물을 받는 빈 손 - 믿음은 의를 받는 통로"}
