        {"상황":"하나님의 사랑을 추상적 개념으로만 아는 성도", "성경원리":"롬 5:7-8의 비교를 통해 하나님의 사랑이 얼마나 구체적이고 역사적인지 드러남", "실제적용":"7절의 비교(의인/선인)와 8절의 실제(죄인)를 통해 하나님 사랑의 구체성과 역사성을 가르치고 십자가 사건을 다시 깊이 묵상하도록 안내"}
