        {"구절":"시 37:4", "연결점":"또 여호와를 기뻐하라 저가 네 마음의 소원을 이루어 주시리로다 - 하나님 안에서의 기쁨", "구분":"구약"},
        {"구절":"고후 5:18", "연결점":"모든 것이 하나님께로 났으며 저가 그리스도로 말미암아 우리를 자기와 화목하게 하시고 - 그리스도로 말미암는 화목", "구분":"신약"},
        {"구절":"요 17:3", "연결점":"영생은 곧 유일하신 참 하나님과 그의 보내신 자 예수 그리스도를 아는 것이니이다 - 하나님 자신을 아는 것이 영생", "구분":"신약"},
        {"구절":"시 73:28", "연결점":"하나님께 가까이 함이 내게 복이라 - 하나님 자신이 복이요 기쁨의 원천", "구분":"구약"}
