        {"구절":"창 2:17", "연결점":"네가 먹는 날에는 반드시 죽으리라 - 죄와 사망의 연결에 대한 최초 선언", "구분":"구약"},
        {"구절":"겔 18:4", "연결점":"범죄하는 그 영혼은 죽으리라 - 죄의 결과는 사망이라는 원리", "구분":"구약"}
