        {"구절":"엡 1:7-8", "연결점":"그의 은혜의 풍성함을 따라 그리스도 안에서 그의 피로 말미암아 구속 곧 죄 사함을 받았으니 이는 그가 모든 지혜와 총명으로 우리에게 넘치게 하심이라", "구분":"신약"},
        {"구절":"요 1:16", "연결점":"우리가 다 그의 충만한 데서 받으니 은혜 위에 은혜러라 - 넘치는 은혜의 충만함", "구분":"신약"},
        {"구절":"고전 15:22", "연결점":"아담 안에서 모든 사람이 죽은 것같이 그리스도 안에서 모든 사람이 삶을 얻으리라", "구분":"신약"},
        {"구절":"사 55:7", "연결점":"우리 하나님께로 돌아오라 그가 너그럽게 용서하시리라 - 넘치는 용서와 은혜", "구분":"구약"}
