        {"구절":"창 1:28", "연결점":"그들로 바다의 고기와 공중의 새와 땅에 움직이는 모든 생물을 다스리라 - 하나님이 창조 때 주신 왕권의 회복", "구분":"구약"},
        {"구절":"딤후 2:12", "연결점":"참으면 또한 함께 왕 노릇할 것이요 - 그리스도와 함께하는 왕권의 약속", "구분":"신약"}
